db()->beginTransaction();transition($users['hod'],$id,'Pending DAA','OK');transition($users['daa'],$id,'Approved','OK');db()->commit();check(one('SELECT status FROM requests WHERE id=?',[$id])['status']==='Approved','sequential approval');check(canView($users['president'],one('SELECT * FROM requests WHERE id=?',[$id])),'president sees approved request');check((int)q('SELECT COUNT(*) FROM outbox WHERE recipient=?',[$users['president']['email']])->fetchColumn()===1,'president only notified upon approval');fails(fn()=>transition($users['daa'],$id,'Approved',''),'stale decision rejected');
