q('INSERT INTO slots(faculty_id,weekday,start_time,end_time,location) VALUES(?,?,?,?,?)',[$users['faculty']['id'],1,'14:00','14:30','Office']);$slot=(int)db()->lastInsertId();$cp=['module'=>'consultation','programme'=>programmes()[0],'purpose'=>'Research','booking_date'=>'2030-10-07','slot_id'=>$slot];db()->beginTransaction();$cid=submitRequest($users['student'],$cp);db()->commit();check(canView($users['faculty'],one('SELECT * FROM requests WHERE id=?',[$cid])),'tutor sees assigned consultation');fails(fn()=>submitRequest($users['student'],$cp),'duplicate slot rejected');$cp['booking_date']='2030-10-08';fails(fn()=>submitRequest($users['student'],$cp),'wrong weekday rejected');db()->beginTransaction();transition($users['faculty'],$cid,'Cancelled','Unavailable');db()->commit();check(!one('SELECT id FROM bookings WHERE request_id=?',[$cid]),'cancelled booking releases slot');
